{"code": "import pandas as pd, statsmodels.formula.api as smf
df = pd.read_csv('data/explore.csv')
expos = ['canopy_cover','soil_moisture','elevation_m','road_dist_km','leaf_litter','temperature_c','slope_deg','nitrate','grazing_index','rainfall_mm']
res=[]
for e in expos:
    d = df.dropna(subset=[e,'species_richness'])
    m = smf.ols(f'species_richness ~ {e} + C(region)', data=d).fit(cov_type='HC3')
    res.append((e, round(m.params[e],4), round(m.pvalues[e],4)))
for r in res: print(r)
"}

{"code": "import pandas as pd, numpy as np, statsmodels.formula.api as smf
df = pd.read_csv('data/explore.csv')
expos = ['canopy_cover','soil_moisture','elevation_m','road_dist_km','leaf_litter','temperature_c','slope_deg','nitrate','grazing_index','rainfall_mm']
# within-region slopes for each exposure
for e in expos:
    slopes=[]
    for r,g in df.dropna(subset=[e,'species_richness']).groupby('region'):
        if len(g)>5:
            m=smf.ols(f'species_richness ~ {e}',data=g).fit()
            slopes.append(round(m.params[e],3))
    print(f"{e:15s} within-region slopes: {slopes}")
"}

